<?= $this->extend(PHARMACY_VIEW . 'layout') ?>
<?= $this->section('main-content') ?>
<main class="pharmacy-page pharmacy-review-page" aria-labelledby="pharmacy-review-title">
    <?= $this->include(PHARMACY_VIEW . 'pages/prescriptions/_toolbar') ?>
    <section class="pharmacy-review-grid" aria-label="Prescription review cards">
    <?php if (($prescriptions ?? []) === []): ?>
        <div class="card pharmacy-review-empty" role="status"><i class="bi bi-inbox d-block" aria-hidden="true"></i><strong>No prescriptions found</strong><span>Try changing the search or filters.</span></div>
    <?php else: foreach ($prescriptions as $prescription): ?>
        <?php $statusClass = in_array($prescription['status'] ?? '', ['approved'], true) ? 'success' : (in_array($prescription['status'] ?? '', ['rejected', 'cancelled'], true) ? 'danger' : 'info'); ?>
        <article class="card prescription-review-card">
            <header class="prescription-card-header"><div class="min-width-0"><span class="review-card-label">Prescription</span><h2 class="h6 mb-0 text-truncate" title="<?= esc($prescription['prescription_number'], 'attr') ?>"><?= esc($prescription['prescription_number']) ?></h2><small class="text-muted"><?= esc($prescription['prescription_date']) ?></small><small class="d-block text-muted"><?= esc($prescription['review_date_label'] ?? 'Last updated') ?>: <?= esc($prescription['review_date'] ?? 'Not recorded') ?></small></div><?= view(PHARMACY_VIEW . 'pages/prescriptions/_actions', ['prescription' => $prescription]) ?></header>
            <div class="prescription-card-patient"><span class="review-card-label">Patient</span><strong class="text-truncate" title="<?= esc($prescription['patient_name'], 'attr') ?>"><?= esc($prescription['patient_name']) ?></strong><span class="text-muted"><?= esc($prescription['patient_number']) ?></span><span class="text-muted text-truncate" title="<?= esc($prescription['patient_mobile'], 'attr') ?>"><?= esc($prescription['patient_mobile']) ?></span></div>
            <div class="prescription-card-details"><span class="min-width-0"><small>Doctor</small><strong class="text-truncate" title="<?= esc($prescription['doctor_name'], 'attr') ?>"><?= esc($prescription['doctor_name']) ?></strong><em><?= esc($prescription['doctor_code']) ?></em></span><span><small>Medicines</small><strong><?= (int) $prescription['medicine_count'] ?></strong><em><?= (int) $prescription['medicine_count'] === 1 ? 'item' : 'items' ?></em></span></div>
            <footer class="prescription-card-footer"><span class="prescription-card-status-group"><small>Prescription status</small><span class="badge badge-<?= $statusClass ?>"><?= esc($prescription['status_label']) ?></span><small>Review: <?= esc($prescription['review_state']) ?></small><small>Valid until <?= esc($prescription['valid_until'] ?? 'Not recorded') ?></small></span><span class="prescription-card-status-group"><small>Cart / order</small><span class="badge badge-light"><?= esc(ucwords(str_replace('_', ' ', $prescription['cart_sync_status'] ?? 'not_synced'))) ?></span><small><?= esc($prescription['shopify_order_reference'] ?? 'Not linked') ?></small></span></footer>
        </article>
    <?php endforeach; endif; ?>
    </section>
    <?= $this->include(PHARMACY_VIEW . 'parts/prescription_pagination') ?>
    <?php if (($uploaded_prescriptions ?? []) !== []): ?><section class="card pharmacy-review-card mt-4" aria-label="Shopify uploaded prescription review queue"><div class="card-body"><div class="d-flex align-items-center justify-content-between mb-3"><div><span class="review-card-label">Shopify uploads</span><h2 class="h6 mb-0">Uploaded prescriptions awaiting pharmacy review</h2></div><span class="badge badge-info"><?= count($uploaded_prescriptions) ?> uploaded</span></div><div class="table-responsive"><table class="table pharmacy-review-table mb-0"><thead><tr><th>Patient</th><th>Upload reference</th><th>Status</th><th>Order</th><th class="text-right">Action</th></tr></thead><tbody><?php foreach ($uploaded_prescriptions as $upload): ?><tr><td><div class="pharmacy-review-stack"><strong><?= esc($upload['patient_name']) ?></strong><span><?= esc($upload['patient_number']) ?></span><span><?= esc($upload['patient_mobile']) ?></span></div></td><td><strong><?= esc($upload['reference']) ?></strong><small class="d-block text-muted">Uploaded document, not a clinical prescription</small></td><td><span class="badge badge-<?= ($upload['status'] ?? '') === 'accepted' ? 'success' : (($upload['status'] ?? '') === 'rejected' ? 'danger' : 'warning') ?>"><?= esc(ucwords(str_replace('_', ' ', $upload['status'] ?? 'uploaded'))) ?></span></td><td><?= !empty($upload['shopify_order_number']) ? 'Shopify #' . esc($upload['shopify_order_number']) : 'Not linked' ?></td><td class="text-right"><?php if ((int) ($upload['import_id'] ?? 0) > 0): ?><a class="btn btn-sm btn-outline-primary" href="<?= base_url('pharmacy/shopify-orders/' . (int) $upload['import_id']) ?>">Review in order</a><?php else: ?><span class="text-muted small">No order linked</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></section><?php endif; ?>
</main>
<?= $this->include(PHARMACY_VIEW . 'pages/prescriptions/_modal') ?>
<?= $this->section('scripts') ?><?= $this->include(PHARMACY_VIEW . 'pages/prescriptions/_scripts') ?><?= $this->endSection() ?>
<?= $this->endSection() ?>
